script:
const words = {
  here: "Where the card was made",
  refresh: "Check the weather",
  empty: "Tap to check the weather",
  which: "Which town?",
  another: "Another town",
  needTown: "Type a town first",
  noTown: "No town called {p0}",
  failed: "Couldn't get the weather: {p0}",
  wind: "Wind {p0} km/h",
  by: "Checked by {p0}",
  clear: "Clear sky",
  cloudy: "Cloudy",
  fog: "Fog",
  rain: "Rain",
  snow: "Snow",
  showers: "Showers",
  storm: "Storm",
};

// Asks open-meteo.com for the weather. The person who taps is asked first.
// Where to look: set when the card was made, or a town typed in the card.
const fixed = null;

function init() {
  return { status: 'empty', place: fixed ? { name: words.here, lat: fixed.lat, lon: fixed.lon } : null };
}

// A town as it goes in a web address.
function query(name) {
  return name.split('').map(c => ' &#?=%+/'.includes(c) ? '%20' : c).join('');
}

function forecast(state, ctx) {
  const p = state.place;
  const r = ctx.fetch('https://api.open-meteo.com/v1/forecast?latitude=' + p.lat + '&longitude=' + p.lon +
    '&current=temperature_2m,weather_code,wind_speed_10m');
  state.by = ctx.authorName;
  if (!r.ok || !r.json || !r.json.current) {
    state.status = 'error';
    state.error = r.error || ('HTTP ' + r.status);
    return;
  }
  const c = r.json.current;
  state.status = 'ok';
  state.temp = c.temperature_2m;
  state.wind = c.wind_speed_10m;
  state.code = c.weather_code;
}

on.refresh = (state, args, ctx) => {
  if (!state.place) throw words.needTown;
  forecast(state, ctx);
};

on.town = (state, args, ctx) => {
  const name = String(args.value || '').trim().slice(0, 60);
  if (!name) throw words.needTown;
  const r = ctx.fetch('https://geocoding-api.open-meteo.com/v1/search?count=1&name=' + query(name));
  if (!r.ok) throw words.failed.replace('{p0}', r.error || ('HTTP ' + r.status));
  const hit = r.json && r.json.results && r.json.results[0];
  if (!hit) throw words.noTown.replace('{p0}', name);
  state.place = { name: hit.country ? hit.name + ', ' + hit.country : hit.name, lat: hit.latitude, lon: hit.longitude };
  forecast(state, ctx);
};

const kinds = [[1, '☀️', words.clear], [3, '⛅', words.cloudy], [48, '🌫️', words.fog], [67, '🌧️', words.rain], [77, '❄️', words.snow], [82, '🌦️', words.showers], [99, '⛈️', words.storm]];
function kind(code) {
  return kinds.find(([max]) => code <= max) || [0, '', ''];
}

function view(state) {
  const parts = [];
  if (state.place) parts.push(text(state.place.name, { bold: true }));
  if (state.status === 'ok') {
    const k = kind(state.code);
    parts.push(text(k[1] + ' ' + Math.round(state.temp) + '°C', { size: 'huge', bold: true, tone: 'accent' }));
    parts.push(row([badge(k[2], { tone: 'accent' }), badge(words.wind.replace('{p0}', Math.round(state.wind)))]));
    parts.push(text(words.by.replace('{p0}', state.by), { size: 'small', tone: 'muted' }));
  } else if (state.status === 'error') {
    parts.push(text(words.failed.replace('{p0}', state.error), { tone: 'danger' }));
  } else if (state.place) {
    parts.push(text(words.empty, { tone: 'muted' }));
  }
  if (state.place) parts.push(button(words.refresh, 'refresh', null, { tone: 'accent' }));
  parts.push(input('town', state.place ? words.another : words.which, 'town'));
  return column(parts);
}
